#!/usr/bin/env bash
# The transport gate: gRPC must produce the SAME assessment as JSON.
#
# `docs/10` accepts the isolated transport change "only if it passes
# identical canonicalization vectors and the applicable acceptance matrix
# without changing those frozen artifacts". The strongest form of that
# test is this: evaluate one snapshot over both transports and compare
# the bytes. If they differ at all, the transport changed a decision,
# and a retained assessment would stop reproducing.
#
# Not a mock on either side. The Rust server is tonic, the Go client is
# generated by protoc-gen-go-grpc, and both come from the same
# `schemas/proto/risk.proto`.
set -euo pipefail

ROOT=$(cd "$(dirname "$0")/.." && pwd)
HTTP_PORT=${HTTP_PORT:-18131}
GRPC_PORT=${GRPC_PORT:-18132}

WORK=$(mktemp -d)
cleanup() {
  # The service is killed deliberately; suppress the shell job notice so
  # a clean run ends on PASS rather than on a Terminated line.
  if [ -n "${SVC:-}" ]; then
    kill "$SVC" 2>/dev/null || true
    wait "$SVC" 2>/dev/null || true
  fi
  rm -rf "$WORK"
}
trap cleanup EXIT

echo "=== building both ends ==="
(cd "$ROOT/risk" && cargo build --quiet -p risk-service)
(cd "$ROOT/gateway" && go build ./...)

echo
echo "=== starting the service on both transports ==="
RISK_SERVICE_ADDR=127.0.0.1:$HTTP_PORT \
  RISK_SERVICE_GRPC_ADDR=127.0.0.1:$GRPC_PORT \
  "$ROOT/risk/target/debug/credence-risk-service" >"$WORK/svc.log" 2>&1 &
SVC=$!

for _ in $(seq 60); do
  if curl -sf "http://127.0.0.1:$HTTP_PORT/health" >/dev/null 2>&1; then break; fi
  sleep 0.25
done
curl -sf "http://127.0.0.1:$HTTP_PORT/health" >/dev/null || {
  echo "FAIL  the service did not come up" >&2
  cat "$WORK/svc.log" >&2
  exit 1
}
grep -q 'grpc listening' "$WORK/svc.log" || {
  echo "FAIL  the gRPC listener did not start" >&2
  cat "$WORK/svc.log" >&2
  exit 1
}
echo "  http 127.0.0.1:$HTTP_PORT"
echo "  grpc 127.0.0.1:$GRPC_PORT"

# A REAL retained snapshot, not one invented here: the gate is about the
# evidence the system actually produces.
SNAP="$ROOT/fixtures/performer/input.json"
POLICY="$ROOT/fixtures/performer/policy.json"
for f in "$SNAP" "$POLICY"; do
  [ -f "$f" ] || { echo "FAIL  missing fixture $f" >&2; exit 1; }
done

echo
echo "=== the same snapshot, over both transports ==="
cd "$ROOT/gateway"
go run ./cmd/credence-transportcheck \
  -http "http://127.0.0.1:$HTTP_PORT" \
  -grpc "127.0.0.1:$GRPC_PORT" \
  -input "$SNAP" \
  -policy "$POLICY"
